ASM_EXPORT(memchr);
//
//      memcmp goes out with the rest of them. build.sh claims it in x86's
//      own string.h so lib/string.c leaves it to us, and a claimed symbol
//      that is not exported is worse than one never claimed: the kernel
//      links, and then every module wanting it fails at modpost with
//      "undefined" -- efivarfs was the one that said so here.
//
//
//      The three the architecture used to write for itself.
//
//      build.sh takes memcpy_64.o, memmove_64.o and memset_64.o out of
//      arch/x86/lib/Makefile, so these are the only definitions left. The
//      kernel names the underscore forms as well -- seventeen references to
//      __memcpy, sixteen to __memset, ten to __memmove -- because that is
//      what instrumented builds route through, so both spellings exist and
//      both go out.
//
ASM_EXPORT(memcpy);
ASM_EXPORT(memmove);
ASM_EXPORT(memset);
ASM_EXPORT(__memcpy);
ASM_EXPORT(__memmove);
ASM_EXPORT(__memset);
ASM_EXPORT(memcmp);
ASM_EXPORT(strchr);
ASM_EXPORT(strchrnul);
ASM_EXPORT(strcmp);
ASM_EXPORT(strcpy);
ASM_EXPORT(strstr);
ASM_EXPORT(strcat);
ASM_EXPORT(strlen);
ASM_EXPORT(strnchr);
ASM_EXPORT(strncmp);
ASM_EXPORT(strnlen);
ASM_EXPORT(strrchr);
//      strcspn and strpbrk are not exported, because they are not claimed --
//      the three edits that make a name ours are the claim, the alias and the
//      export, and all three came out together when the bodies turned out to
//      be outside every kernel build. An export without a definition is what
//      modpost calls "references X, but it does not seem to be an export
//      symbol"; an export beside the kernel's own is "exported twice". This
//      block saw both in one afternoon.
